@startuml

class Airline {
  + ID
  + name
}

class Flight {
  + ID
  + departure_time
  + arrival_time
}

class Airport {
  + ID
  + name
}

class Aircraft {
  + name
  + repair
  + landed
}

class AircraftType {
  + name
}

class Pilot {
  + name
  + experience_level
}

Airline "1" -- "*" Flight : operates
Airline "1" -- "*" Aircraft : owns
Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives to
Flight "*" -- "1" Aircraft : uses
Aircraft "*" -- "1" AircraftType : is of
AircraftType "1" -- "1..* Captain" Pilot
AircraftType "1" -- "1..* Co-pilot" Pilot
AircraftType "1" -- "1..* Navigator" Pilot

@enduml

